EMBEDDED = ''

def fetch(item):
    destination = ROOT / item['path']
    for attempt in range(3):
        try:
            request = urllib.request.Request(BASE + item['path'], headers={'User-Agent': 'Venomics-website-export/1.0'})
            with urllib.request.urlopen(request, timeout=90) as response:
                data = response.read()
            if len(data) != item['size'] or hashlib.sha256(data).hexdigest() != item['sha256']:
                raise ValueError('Export checksum mismatch: ' + item['path'])
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_bytes(data)
            print('Verified ' + item['path'], flush=True)
            return
        except Exception:
            if attempt == 2:
                raise
            time.sleep(2 * (attempt + 1))

if __name__ == '__main__':
    with ThreadPoolExecutor(max_workers=4) as pool:
        list(pool.map(fetch, MANIFEST))
    for name, encoded in json.loads(zlib.decompress(base64.b64decode(EMBEDDED))).items():
        destination = ROOT / name
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(base64.b64decode(encoded))
    print('Imported and verified all export assets and narration.')
